Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='cachemarkshared', at=datetime(2026, 11, 28, 5, 51, 28, 796749), actor='assistant', title='A model call marks a cache point only after a prefix that another call shares', body='A call that shares its log with other calls of the same burst puts the cache mark after that log, so the later calls read it from the cache. A call that shares no prefix with another call sends no mark.', rationale='A cache write costs more than the same tokens read plainly, and a lone call never reads its write back. Before pull request 679 the compaction calls marked every call and read about 2 percent of their input from the cache; with the log frozen per burst and the mark after it, generated data read about 98 percent.', supersedes=()))